import type { MenuCheckboxItemProps } from "./menu-item/menu-item.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Checkbox } from "@components/checkbox";

import { useMenu } from "../hooks/use-menu";

import { StyledMenuItem, MenuItemClasses } from "./menu-item/menu-item.styles";
import { MenuItemLabel, MenuItemText } from "./menu-item";

const MenuCheckboxItem = forwardRef<HTMLDivElement, MenuCheckboxItemProps>(
  (
    {
      children,
      className,
      onSelect: propOnSelect,
      variant: variantProp,
      styleSlots,
      style,
      checked,
      onCheckedChange,
      closeOnSelect = false,
      size: sizeProp,
      ...props
    },
    ref,
  ) => {
    const { onSelect: contextOnSelect, RadixComponent, variant, size: contextSize } = useMenu();
    const theme = useTheme();
    const size = sizeProp || contextSize;
    const menuItemClasses = clsx(
      MenuItemClasses.root,
      {
        [MenuItemClasses.sm]: size === "sm",
      },
      className,
    );

    const handleSelect = (event: Event | React.SyntheticEvent<HTMLElement, Event>) => {
      const nativeEvent = event as Event;
      if (!closeOnSelect) {
        nativeEvent.preventDefault();
      }
      propOnSelect?.(nativeEvent);
      contextOnSelect?.(nativeEvent);
    };

    const content = React.Children.map(children, (child) =>
      typeof child === "string" ? <MenuItemLabel>{child}</MenuItemLabel> : child,
    );

    const hasSubtext = React.Children.toArray(content).some(
      (child) =>
        React.isValidElement(child) &&
        (child.type as { displayName?: string }).displayName === "Menu.ItemSubtext",
    );

    const contentWithTextWrapper = hasSubtext ? (
      <MenuItemText key="menu-item-text">
        {React.Children.toArray(content).filter(
          (child) =>
            React.isValidElement(child) &&
            (child.type as { displayName?: string }).displayName !== "Menu.ItemLeadingIcon" &&
            (child.type as { displayName?: string }).displayName !== "Menu.ItemTrailingIcon" &&
            (child.type as { displayName?: string }).displayName !== "Menu.ItemHotkey",
        )}
      </MenuItemText>
    ) : (
      content
    );
    return (
      <StyledMenuItem
        ref={ref}
        as={RadixComponent.CheckboxItem}
        checked={checked}
        className={menuItemClasses}
        currentTheme={theme}
        data-has-subtext={hasSubtext ? true : undefined}
        style={style}
        styleSlots={styleSlots}
        variant={variantProp || variant}
        onCheckedChange={onCheckedChange}
        onSelect={handleSelect}
        {...props}
      >
        <div className={MenuItemClasses.leadingIcon}>
          <Checkbox checked={checked} />
        </div>
        {hasSubtext
          ? [
              React.Children.toArray(content).find(
                (child) =>
                  React.isValidElement(child) &&
                  (child.type as { displayName?: string }).displayName === "Menu.ItemLeadingIcon",
              ),
              contentWithTextWrapper,
              React.Children.toArray(content).find(
                (child) =>
                  React.isValidElement(child) &&
                  (child.type as { displayName?: string }).displayName === "Menu.ItemTrailingIcon",
              ),
              React.Children.toArray(content).find(
                (child) =>
                  React.isValidElement(child) &&
                  (child.type as { displayName?: string }).displayName === "Menu.ItemHotkey",
              ),
            ]
          : content}
      </StyledMenuItem>
    );
  },
);
MenuCheckboxItem.displayName = "Menu.CheckboxItem";

export { MenuCheckboxItem };
